def parse_sam(path):
    recs=[]
    for line in open(path):
        if not line.strip() or line.startswith('@'): continue
        f=line.rstrip('\n').split('\t')
        if len(f)<11: continue
        tags={}
        for x in f[11:]:
            z=x.split(':',2)
            if len(z)==3: tags[z[0]]=z[2]
