    return recs

def aligned(rec, refseq):
    """Return refpos -> read base/read index and a list of alignment events.
    Coordinates are 1-based reference positions. For insertions, key=(I, anchor).
    """
    rp=rec['pos']; qi=0; out={}; events=[]; aligned_ref=[]
    for n,op in cigar_ops(rec['cigar']):
        if op in 'M=X':
            for k in range(n):
                q=qi+k; r=rp+k
                out[r]=(rec['seq'][q],q,rec['qual'][q])
                aligned_ref.append((r,rec['seq'][q]))
            rp+=n; qi+=n
        elif op=='I':
            out[('I',rp)]=(rec['seq'][qi:qi+n],qi,None)
            events.append(('I',rp,rec['seq'][qi:qi+n])); qi+=n
        elif op=='D':
            for k in range(n):
                r=rp+k
                out[('D',r)]=('-',None,None)
                events.append(('D',r,refseq[r-1] if r<=len(refseq) else '?'))
            rp+=n
        elif op=='N':
            rp+=n; qi+=n
        elif op=='S':
